<!-- Copyright © 2026 上海如静知华信息科技有限公司 · https://www.zhuatech.cn/ --><script setup>
import{ref}from'vue';const password=ref(''),rows=ref(100),seed=ref(42),result=ref(null),error=ref('');
const fields=[{name:'customer_name',type:'NAME',nullRate:0,unique:false,sensitive:true,min:1,max:100,categories:[],startDate:'2025-01-01',endDate:'2026-12-31'},{name:'segment',type:'CATEGORY',nullRate:0,unique:false,sensitive:false,min:1,max:100,categories:['制造业','零售业','专业服务','科技'],startDate:'2025-01-01',endDate:'2026-12-31'},{name:'annual_value',type:'MONEY',nullRate:.05,unique:false,sensitive:false,min:1000,max:500000,categories:[],startDate:'2025-01-01',endDate:'2026-12-31'}];
async function generate(){try{const body={requestId:'SYN-'+Date.now(),rowCount:rows.value,seed:seed.value,fields,privacyReviewed:true,requesterId:'data-engineer',approverId:'privacy-owner'};const r=await fetch('/api/synthetic-data/generate',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Basic '+btoa('admin:'+password.value)},body:JSON.stringify(body)});if(!r.ok)throw Error('请求失败：'+r.status);result.value=(await r.json()).data;error.value='';}catch(e){error.value=e.message;}}</script>
<template><div class="shell"><aside><h2>ZH Synthetic Data</h2><nav>生成工作台<br>Schema 模板<br>隐私评估<br>数据导出<br>审计记录</nav><a href="https://www.zhuatech.cn/">知华科技</a></aside><main><header><div><small>AI 数据工程 / 测试数据空间</small><h1>合成数据生成工作台</h1></div><input v-model="password" type="password" placeholder="管理员密码"></header><section class="cards"><article><b>8</b><span>字段生成器</span></article><article><b>可复现</b><span>确定性种子</span></article><article><b>默认掩码</b><span>敏感字段预览</span></article></section><div class="grid"><section class="panel"><h2>生成配置</h2><div class="cols"><label>数据行数<input v-model.number="rows" type="number"></label><label>随机种子<input v-model.number="seed" type="number"></label></div><table><thead><tr><th>字段</th><th>类型</th><th>敏感</th></tr></thead><tbody><tr v-for="f in fields"><td>{{f.name}}</td><td>{{f.type}}</td><td>{{f.sensitive?'是':'否'}}</td></tr></tbody></table><button @click="generate">生成并评估</button><em>{{error}}</em></section><section class="panel"><h2>隐私与导出结论</h2><template v-if="result"><strong>{{result.decision}}</strong><p>风险等级：{{result.riskLevel}}</p><ul><li v-for="x in result.warnings">{{x}}</li></ul><pre>{{JSON.stringify(result.preview.slice(0,5),null,2)}}</pre></template><p v-else>生成后显示掩码预览、风险和导出门禁。</p></section></div></main></div></template>
